#!/usr/bin/env python3
"""Week 7 · harness for Task 3. Do not edit this file.

A switch does not have room for every station on the network. Its forwarding
table lives in a fixed amount of fast memory, and when that fills up something
has to be thrown out. Whatever you throw out gets flooded the next time somebody
sends to it.

    switch     48 ports, table holds 64 entries
    network    400 stations behind those ports
    trace      60,000 frames, Zipf-distributed - a few stations do most of the talking
    scored     wasted deliveries - frames handed to a port that did not want them
    checked    every deliverable frame still has to be delivered

    python3 bench.py
    python3 bench.py --yours
"""
import argparse, random

SEED, PORTS, STATIONS, CAPACITY, FRAMES = 246, 48, 400, 64, 60_000
BROADCAST = "ff:ff:ff:ff:ff:ff"


def build(seed=SEED):
    rng = random.Random(seed)
    macs = [f"00:00:00:{i // 65536:02x}:{i // 256 % 256:02x}:{i % 256:02x}"
            for i in range(STATIONS)]
    where = {m: rng.randrange(PORTS) for m in macs}

    # A few stations carry most of the traffic, as on any real segment.
    weights = [1 / (i + 1) ** 1.5 for i in range(STATIONS)]
    frames = []
    for i in range(FRAMES):
        src = rng.choices(macs, weights)[0]
        r = rng.random()
        if r < 0.03:
            dst = BROADCAST
        else:
            dst = rng.choices(macs, weights)[0]
            if dst == src:
                continue
        frames.append((src, dst, i / 10.0, where[src]))
    return macs, where, frames


def run(cls, label, where, frames):
    sw = cls(PORTS, CAPACITY)
    wasted = delivered = missed = 0
    for src, dst, t, in_port in frames:
        out = sw.handle((src, dst, t), in_port)
        if len(getattr(sw, "table", {})) > CAPACITY:
            raise RuntimeError(
                f"{label}: table holds {len(sw.table)} entries, capacity is {CAPACITY}")
        if dst == BROADCAST:
            wasted += max(0, len(out) - (PORTS - 1))
            continue
        want = where[dst]
        if want == in_port:
            continue
        if want in out:
            delivered += 1
            wasted += len(out) - 1
        else:
            missed += 1
            wasted += len(out)
    print(f"  {label:<12} wasted {wasted:>9,}   delivered {delivered:>6,}   "
          f"missed {missed:>6,}")
    return {"wasted": wasted, "delivered": delivered, "missed": missed}


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--yours", action="store_true")
    a = p.parse_args()

    macs, where, frames = build()
    print(f"\n  {PORTS} ports, {STATIONS} stations, table capacity {CAPACITY}, "
          f"{len(frames):,} frames\n")

    from task3_flooding import NaiveSwitch
    base = run(NaiveSwitch, "baseline", where, frames)

    if a.yours:
        from task3_flooding import YourSwitch
        mine = run(YourSwitch, "yours", where, frames)
        print()
        if mine["missed"] > base["missed"]:
            print(f"   FAIL  {mine['missed'] - base['missed']:,} more frames missed "
                  f"their destination than the baseline.")
        else:
            cut = 1 - mine["wasted"] / base["wasted"]
            print(f"   ok    no additional missed deliveries")
            print(f"   wasted deliveries cut by {cut:.0%}")
            grade = ("strong" if cut >= 0.45 else
                     "good" if cut >= 0.25 else
                     "pass" if cut > 0.02 else "not yet")
            print(f"\n   -> {grade}")
    print()


if __name__ == "__main__":
    main()
